CREATE TABLE IF NOT EXISTS ai_news_articles(id TEXT PRIMARY KEY,nation_id TEXT NOT NULL CHECK(nation_id IN ('kindle','korund','aurelle')),title TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL,model TEXT NOT NULL,facts_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_news_jobs(id TEXT PRIMARY KEY,nation_id TEXT NOT NULL CHECK(nation_id IN ('kindle','korund','aurelle')),utc_day TEXT NOT NULL,started_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('running','published','failed')),failure_code TEXT);
CREATE TABLE IF NOT EXISTS harimu_ai_reservations (request_id TEXT PRIMARY KEY,utc_day TEXT NOT NULL,next_utc_day TEXT NOT NULL,model TEXT NOT NULL,reserved_micro INTEGER NOT NULL CHECK(reserved_micro>0),started_at INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','finished','uncertain')));
CREATE TABLE IF NOT EXISTS korund_ration_queue (seq INTEGER PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,clerk_user_id TEXT NOT NULL REFERENCES citizens(clerk_user_id),game_week INTEGER NOT NULL CHECK(game_week>=1),joined_at INTEGER NOT NULL,expires_at INTEGER NOT NULL CHECK(expires_at>joined_at),status TEXT NOT NULL DEFAULT 'waiting' CHECK(status IN ('waiting','cancelled','redeemed')));
CREATE TABLE IF NOT EXISTS korund_queue_cancellations (request_id TEXT PRIMARY KEY,queue_id TEXT NOT NULL REFERENCES korund_ration_queue(request_id),clerk_user_id TEXT NOT NULL REFERENCES citizens(clerk_user_id),cancelled_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_korund_queue_waiting ON korund_ration_queue(clerk_user_id,game_week) WHERE status='waiting';
